#!/usr/bin/env bash
set -euo pipefail

# ==============================================================================
# deploy-github.sh
# 
# Creates a GitHub Release for SlackHacks using the GitHub REST API and uploads
# the packaged zip artifact generated by build.sh.
#
# Prerequisites:
# 1. Proton Pass CLI (pass-cli) installed and authenticated.
# 2. GitHub Personal Access Token (classic or fine-grained with 'contents: write')
#    stored in Proton Pass.
# ==============================================================================

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# ------------------------------------------------------------------------------
# Configurable Variables & Settings (Please confirm / adjust as needed)
# ------------------------------------------------------------------------------
# GitHub repository in "owner/repo" format.
GITHUB_REPO="${GITHUB_REPO:-"Slackwise/SlackHacks"}"

# Release branch or commit SHA (default: "main" or current branch)
TARGET_COMMITISH="${TARGET_COMMITISH:-"main"}"

# Set to "true" to create as a draft release, "false" to publish immediately
IS_DRAFT="${IS_DRAFT:-false}"

# Set to "true" to mark as a pre-release
IS_PRERELEASE="${IS_PRERELEASE:-false}"

# Set to "true" to let GitHub automatically generate release notes from commits/PRs
GENERATE_RELEASE_NOTES="${GENERATE_RELEASE_NOTES:-true}"

# Optional path to a custom release notes/changelog file (takes precedence if non-empty)
CHANGELOG_FILE="${CHANGELOG_FILE:-""}"

# Proton Pass CLI settings for retrieving the GitHub Personal Access Token:
# Item title/name in your Proton Pass vault
PROTON_PASS_ITEM="${PROTON_PASS_ITEM:-"GitHub"}"
# Vault name (leave empty if using the default vault)
PROTON_PASS_VAULT="${PROTON_PASS_VAULT:-""}"
# Attribute to retrieve (e.g., "password" or a custom field name)
PROTON_PASS_ATTRIBUTE="${PROTON_PASS_ATTRIBUTE:-"password"}"
# Binary name or path for Proton Pass CLI
PROTON_PASS_CLI_BIN="${PROTON_PASS_CLI_BIN:-"pass-cli"}"

# ------------------------------------------------------------------------------
# Helper: Fetch secret from Proton Pass CLI
# ------------------------------------------------------------------------------
fetch_secret_from_proton_pass() {
  local item="$1"
  local vault="$2"
  local attr="$3"

  # Allow environment variable override if already set
  if [[ -n "${GITHUB_TOKEN:-}" ]]; then
    echo "$GITHUB_TOKEN"
    return 0
  fi

  if ! command -v "$PROTON_PASS_CLI_BIN" >/dev/null 2>&1; then
    echo "Error: Proton Pass CLI ('$PROTON_PASS_CLI_BIN') was not found in PATH." >&2
    echo "Please ensure the Proton Pass CLI is installed and in your PATH, or set GITHUB_TOKEN directly." >&2
    return 1
  fi

  local secret=""
  if [[ -n "$vault" ]]; then
    secret=$("$PROTON_PASS_CLI_BIN" item get "$item" --vault "$vault" --attribute "$attr" 2>/dev/null || true)
  else
    secret=$("$PROTON_PASS_CLI_BIN" item get "$item" --attribute "$attr" 2>/dev/null || true)
  fi

  # Clean whitespace and carriage returns
  secret="$(echo "$secret" | tr -d '\r\n' | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"

  if [[ -z "$secret" ]]; then
    echo "Error: Could not retrieve secret for item '$item' from Proton Pass." >&2
    echo "Command attempted: $PROTON_PASS_CLI_BIN item get \"$item\" ${vault:+--vault \"$vault\"} --attribute \"$attr\"" >&2
    return 1
  fi

  echo "$secret"
}

# ------------------------------------------------------------------------------
# Step 1: Ensure build output is ready
# ------------------------------------------------------------------------------
TOC_FILE="SlackHacks.toc"
if [[ ! -f "$TOC_FILE" ]]; then
  echo "Error: $TOC_FILE not found in $SCRIPT_DIR" >&2
  exit 1
fi

VERSION=$(grep -i '^[[:space:]]*##[[:space:]]*Version:' "$TOC_FILE" | head -n 1 | sed -E 's/^[[:space:]]*##[[:space:]]*[Vv]ersion:[[:space:]]*//' | tr -d '\r\n')
VERSION="$(echo "$VERSION" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"

if [[ -z "$VERSION" ]]; then
  echo "Error: Could not determine version from $TOC_FILE." >&2
  exit 1
fi

FOLDER_NAME="SlackHacks-v${VERSION#v}"
TAG_NAME="v${VERSION#v}"
RELEASE_TITLE="SlackHacks v${VERSION#v}"
ZIP_NAME="${FOLDER_NAME}.zip"
ZIP_PATH="dist/${ZIP_NAME}"

if [[ ! -f "$ZIP_PATH" ]]; then
  echo "Zip archive $ZIP_PATH not found. Running build.sh first..."
  bash ./build.sh
fi

if [[ ! -f "$ZIP_PATH" ]]; then
  echo "Error: Build output $ZIP_PATH is still missing after running build.sh." >&2
  exit 1
fi

echo "Found release archive: $ZIP_PATH"

# ------------------------------------------------------------------------------
# Step 2: Retrieve GitHub Token from Proton Pass
# ------------------------------------------------------------------------------
echo "Fetching GitHub Token from Proton Pass..."
GITHUB_TOKEN="$(fetch_secret_from_proton_pass "$PROTON_PASS_ITEM" "$PROTON_PASS_VAULT" "$PROTON_PASS_ATTRIBUTE")"
if [[ -z "$GITHUB_TOKEN" ]]; then
  exit 1
fi
echo "Successfully retrieved GitHub Token."

# ------------------------------------------------------------------------------
# Step 3: Prepare Release Notes / Body
# ------------------------------------------------------------------------------
escape_json() {
  local str="$1"
  if command -v python3 >/dev/null 2>&1; then
    python3 -c 'import json, sys; print(json.dumps(sys.stdin.read())[1:-1], end="")' <<< "$str"
  elif command -v python >/dev/null 2>&1; then
    python -c 'import json, sys; print(json.dumps(sys.stdin.read())[1:-1], end="")' <<< "$str"
  else
    echo "$str" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g' | awk '{printf "%s\\n", $0}' | sed 's/\\n$//'
  fi
}

RELEASE_BODY=""
if [[ -n "$CHANGELOG_FILE" && -f "$CHANGELOG_FILE" ]]; then
  RELEASE_BODY="$(cat "$CHANGELOG_FILE")"
fi

ESCAPED_BODY="$(escape_json "$RELEASE_BODY")"

# ------------------------------------------------------------------------------
# Step 4: Create GitHub Release
# ------------------------------------------------------------------------------
echo "=== GitHub Release Summary ==="
echo "Repository:          ${GITHUB_REPO}"
echo "Tag Name:            ${TAG_NAME}"
echo "Target Commit/Branch:${TARGET_COMMITISH}"
echo "Release Title:       ${RELEASE_TITLE}"
echo "Draft:               ${IS_DRAFT}"
echo "Prerelease:          ${IS_PRERELEASE}"
echo "Auto Release Notes:  ${GENERATE_RELEASE_NOTES}"
echo "Artifact:            ${ZIP_PATH}"
echo "=============================="

PAYLOAD=$(cat <<EOF
{
  "tag_name": "${TAG_NAME}",
  "target_commitish": "${TARGET_COMMITISH}",
  "name": "${RELEASE_TITLE}",
  "body": "${ESCAPED_BODY}",
  "draft": ${IS_DRAFT},
  "prerelease": ${IS_PRERELEASE},
  "generate_release_notes": ${GENERATE_RELEASE_NOTES}
}
EOF
)

API_URL="https://api.github.com/repos/${GITHUB_REPO}/releases"

echo "Creating GitHub Release..."
CREATE_RESPONSE=$(curl -s -S -w "\nHTTP_STATUS:%{http_code}" \
  -X POST \
  -H "Accept: application/vnd.github+json" \
  -H "Authorization: Bearer ${GITHUB_TOKEN}" \
  -H "X-GitHub-Api-Version: 2022-11-28" \
  -d "$PAYLOAD" \
  "$API_URL")

HTTP_STATUS=$(echo "$CREATE_RESPONSE" | grep "HTTP_STATUS:" | cut -d':' -f2)
BODY=$(echo "$CREATE_RESPONSE" | sed -e '/HTTP_STATUS:/d')

if [[ "$HTTP_STATUS" -lt 200 || "$HTTP_STATUS" -ge 300 ]]; then
  echo "Error: Failed to create GitHub Release (HTTP $HTTP_STATUS)." >&2
  echo "Response: $BODY" >&2
  exit 1
fi

# Extract release ID and HTML URL from response
parse_json_field() {
  local json="$1"
  local field="$2"
  if command -v python3 >/dev/null 2>&1; then
    python3 -c "import json, sys; d=json.loads(sys.stdin.read()); print(d.get('$field', ''))" <<< "$json"
  elif command -v python >/dev/null 2>&1; then
    python -c "import json, sys; d=json.loads(sys.stdin.read()); print(d.get('$field', ''))" <<< "$json"
  else
    echo "$json" | grep -o "\"$field\":[^,}]*" | head -n 1 | cut -d':' -f2- | tr -d ' "'
  fi
}

RELEASE_ID="$(parse_json_field "$BODY" "id")"
RELEASE_HTML_URL="$(parse_json_field "$BODY" "html_url")"

if [[ -z "$RELEASE_ID" ]]; then
  echo "Error: Could not extract release ID from GitHub response." >&2
  echo "Response: $BODY" >&2
  exit 1
fi

echo "Created release successfully (ID: $RELEASE_ID): $RELEASE_HTML_URL"

# ------------------------------------------------------------------------------
# Step 5: Upload Zip Asset
# ------------------------------------------------------------------------------
UPLOAD_URL="https://uploads.github.com/repos/${GITHUB_REPO}/releases/${RELEASE_ID}/assets?name=${ZIP_NAME}"

echo "Uploading asset ${ZIP_NAME} to GitHub release..."
UPLOAD_RESPONSE=$(curl -s -S -w "\nHTTP_STATUS:%{http_code}" \
  -X POST \
  -H "Accept: application/vnd.github+json" \
  -H "Authorization: Bearer ${GITHUB_TOKEN}" \
  -H "Content-Type: application/zip" \
  -H "X-GitHub-Api-Version: 2022-11-28" \
  --data-binary @"${ZIP_PATH}" \
  "$UPLOAD_URL")

UPLOAD_HTTP_STATUS=$(echo "$UPLOAD_RESPONSE" | grep "HTTP_STATUS:" | cut -d':' -f2)
UPLOAD_BODY=$(echo "$UPLOAD_RESPONSE" | sed -e '/HTTP_STATUS:/d')

if [[ "$UPLOAD_HTTP_STATUS" -ge 200 && "$UPLOAD_HTTP_STATUS" -lt 300 ]]; then
  echo "Asset uploaded successfully (HTTP $UPLOAD_HTTP_STATUS)!"
  echo "Release URL: $RELEASE_HTML_URL"
else
  echo "Error: Asset upload failed with HTTP status $UPLOAD_HTTP_STATUS." >&2
  echo "Response: $UPLOAD_BODY" >&2
  exit 1
fi
